    76|// Validate date of birth: required, ISO YYYY-MM-DD, real calendar date, age 18-120
    77|function validateDateOfBirth(dateOfBirth: string): { valid: boolean; reason?: string } {
    78|  if (!dateOfBirth) return { valid: false, reason: 'Date of birth is required.' };
    79|  const match = dateOfBirth.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    80|  if (!match) return { valid: false, reason: 'Date of birth must be in YYYY-MM-DD format.' };
    81|  const year = Number(match[1]);
    82|  const month = Number(match[2]);
    83|  const day = Number(match[3]);
    84|  if (month < 1 || month > 12) return { valid: false, reason: 'Please enter a valid date of birth.' };
    85|  const daysInMonth = new Date(Date.UTC(year, month, 0)).getUTCDate();
    86|  if (day < 1 || day > daysInMonth) return { valid: false, reason: 'Please enter a valid date of birth.' };
